27.  * method-annotations.
28.  */
29. public class ZeebeWorkerAnnotationProcessor extends AbstractZeebeAnnotationProcessor {
30. 
31.   private static final Logger LOGGER =
32.       LoggerFactory.getLogger(MethodHandles.lookup().lookupClass());
33. 
34.   private final JobWorkerManager jobWorkerManager;
35. 
36.   private final List<ZeebeWorkerValue> zeebeWorkerValues = new ArrayList<>();
37.   private final List<ZeebeWorkerValueCustomizer> zeebeWorkerValueCustomizers;
