39.   public ZeebeWorkerAnnotationProcessor(
40.       final JobWorkerManager jobWorkerFactory,
41.       final List<ZeebeWorkerValueCustomizer> zeebeWorkerValueCustomizers) {
42.     this.jobWorkerManager = jobWorkerFactory;
43.     this.zeebeWorkerValueCustomizers = zeebeWorkerValueCustomizers;
