46.   @Override
47.   public boolean isApplicableFor(ClassInfo beanInfo) {
48.     return beanInfo.hasMethodAnnotation(JobWorker.class)
49.         || beanInfo.hasMethodAnnotation(ZeebeWorker.class);
50.   }
