52.   @Override
53.   public void configureFor(ClassInfo beanInfo) {
54.     List<ZeebeWorkerValue> newZeebeWorkerValues = new ArrayList<>();
55. 
56.     doWithMethods(
57.         beanInfo.getTargetClass(),
58.         method ->
