       builder.fetchVariables(zeebeWorkerValue.getFetchVariables());
     }
     if (zeebeWorkerValue.getTenantIds() != null && !zeebeWorkerValue.getTenantIds().isEmpty()) {
       builder.tenantIds(zeebeWorkerValue.getTenantIds());
